export type AllowanceState = "healthy" | "low" | "empty" | "reserved";

/** Presentation only: the provider remains authoritative for all counts. */
export function getAllowanceState({
  remaining,
  total,
  queued,
}: {
  remaining: number;
  total: number;
  queued: number;
}): AllowanceState {
  if (total <= 0) return "empty";
  if (remaining <= 0) return queued > 0 ? "reserved" : "empty";
  return remaining / total <= 0.2 ? "low" : "healthy";
}
